from by_lib import *


def R(code, name, short, pop, pcrel, dev, unrest, auto, reg, tr, sec, infra, edu, health, env, mix, desc, E, Ecal=None):
    return dict(code=code, name=name, short=short, pop=pop, pcrel=pcrel, dev=dev, unrest=unrest, auto=auto, reg=reg, tr=tr,
                sec={"ind": sec[0], "agr": sec[1], "srv": sec[2], "res": sec[3]}, infra=infra, edu=edu, health=health, env=env, mix=mix, desc=desc, E=E, Ecal=Ecal)


def E24(br, kpb, rpts, ldp, ind, against):
    """официальные итоги 2024 года по области (оценка долей голосов по округам): слоты 0..9; «против всех» — к прочим"""
    return [br, kpb, rpts, ldp, 0.0, 0.0, against, 0.0, ind, 0.0]


def Ecal(row, lib, green, natdem, demf):
    """для калибровки: официальные доли + региональный профиль сил, не допущенных к выборам (оценка по протестам 2020 года и опросам эмиграции)"""
    r = list(row); r[4] = lib; r[5] = green; r[7] = natdem; r[9] = demf
    return r


